import React, { useRef, useEffect } from 'react';
import { createSpring } from '../hooks/useSpring';

// Each letter has its own set of springs
function makeSprings() {
  return {
    weight:  createSpring(60, 11),
    stretch: createSpring(60, 11),
    slant:   createSpring(60, 11),
    size:    createSpring(60, 11),
    spacing: createSpring(60, 11),
  };
}

export default function TypeRenderer({ typeProps, word, baseSize }) {
  const canvasRef = useRef(null);
  const springs   = useRef(null);
  const raf       = useRef(null);
  const propsRef  = useRef(typeProps);

  // Keep ref in sync
  useEffect(() => { propsRef.current = typeProps; }, [typeProps]);

  // Init springs per letter
  useEffect(() => {
    springs.current = word.split('').map(() => makeSprings());
  }, [word]);

  // Update spring targets when typeProps change
  useEffect(() => {
    if (!springs.current || !typeProps) return;
    springs.current.forEach(s => {
      s.weight.setTarget(typeProps.weight);
      s.stretch.setTarget(typeProps.stretch);
      s.slant.setTarget(typeProps.slant);
      s.size.setTarget(typeProps.size);
      s.spacing.setTarget(typeProps.spacing);
    });
  }, [typeProps]);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');

    // Ensure springs exist
    if (!springs.current) {
      springs.current = word.split('').map(() => makeSprings());
    }

    let last = performance.now();

    const draw = (now) => {
      const dt = Math.min((now - last) / 1000, 0.05);
      last = now;

      const W = canvas.width, H = canvas.height;
      ctx.clearRect(0, 0, W, H);

      const letters = word.split('');
      if (!letters.length) { raf.current = requestAnimationFrame(draw); return; }

      // Step springs
      const vals = springs.current.map(s => ({
        weight:  s.weight.step(dt),
        stretch: s.stretch.step(dt),
        slant:   s.slant.step(dt),
        size:    s.size.step(dt),
        spacing: s.spacing.step(dt),
      }));

      // Measure total width first for centering
      const letterBase = baseSize || H * 0.62;
      const measureFontSize = letterBase;

      let totalWidth = 0;
      const metrics = vals.map((v, i) => {
        const fs = Math.round(measureFontSize * v.size);
        const fw = Math.round(v.weight);
        ctx.font = `${fw} ${fs}px Helvetica Neue, Helvetica, Arial, sans-serif`;
        const m = ctx.measureText(letters[i]);
        const lw = m.width * (v.stretch / 100);
        const sp = fs * v.spacing;
        totalWidth += lw + sp;
        return { fs, fw, lw, sp, ...v };
      });

      // Draw each letter
      let x = (W - totalWidth) / 2;
      const cy = H / 2;

      letters.forEach((ch, i) => {
        const v = metrics[i];
        const fs = v.fs;

        ctx.save();

        // Apply slant via transform
        const slantRad = v.slant * Math.PI / 180;
        const translateX = -slantRad * (fs * 0.3);
        ctx.transform(1, 0, -Math.tan(slantRad), 1, x + v.lw / 2 + translateX, cy + fs * 0.35);
        ctx.scale(v.stretch / 100, 1);

        ctx.font = `${v.fw} ${fs}px Helvetica Neue, Helvetica, Arial, sans-serif`;
        ctx.fillStyle = '#0a0a0a';
        ctx.textAlign = 'center';
        ctx.textBaseline = 'alphabetic';
        ctx.fillText(ch, 0, 0);

        ctx.restore();

        x += v.lw + v.sp;
      });

      raf.current = requestAnimationFrame(draw);
    };

    raf.current = requestAnimationFrame(draw);
    return () => cancelAnimationFrame(raf.current);
  }, [word, baseSize]);

  return (
    <canvas
      ref={canvasRef}
      width={900}
      height={300}
      style={{ display:'block', width:'100%', height:'100%' }}
    />
  );
}
